import{at as e,it as t,o as n,vt as r}from"./chunks/framework.DQt_9H6f.js";var i=JSON.parse(`{"title":"Memory","description":"","frontmatter":{},"headers":[],"relativePath":"guide/memory.md","filePath":"guide/memory.md"}`),a={name:`guide/memory.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="memory" tabindex="-1">Memory <a class="header-anchor" href="#memory" aria-label="Permalink to “Memory”">​</a></h1><p>The assistant (and the helper agents it starts) keep notes that persist across conversations. The next time you start a chat, even days later, the assistant sees an index of those notes and picks up where it left off without needing to re-explain the project.</p><h2 id="what-memory-is-for" tabindex="-1">What memory is for <a class="header-anchor" href="#what-memory-is-for" aria-label="Permalink to “What memory is for”">​</a></h2><p>Memory is for facts the assistant should remember about <strong>you</strong> and <strong>your project</strong>, not the conversation itself. Good things to keep:</p><ul><li>Conventions you want enforced (label prefixes, citation styles, notation choices)</li><li>Project structure (where figures live, which file is the main document)</li><li>Decisions you&#39;ve made that the assistant would otherwise revisit</li><li>Pitfalls you keep hitting (a compiler quirk, a finicky package, a flaky reference)</li><li>Your own preferences that hold in every project (spelling, tone, how much explanation you want)</li></ul><p>Memory is <strong>not</strong> a chat transcript. The assistant doesn&#39;t replay old conversations; it reads the notes.</p><h2 id="memory-is-two-folders-of-markdown-files" tabindex="-1">Memory is two folders of Markdown files <a class="header-anchor" href="#memory-is-two-folders-of-markdown-files" aria-label="Permalink to “Memory is two folders of Markdown files”">​</a></h2><p>There is no memory tool. Notes are ordinary Markdown files in two folders, which the assistant reads and writes with the same file tools it uses on your project:</p><table tabindex="0"><thead><tr><th>Folder</th><th>What belongs in it</th><th>Where it is</th></tr></thead><tbody><tr><td><strong>Your memory</strong></td><td>What is true of you, in every project</td><td><code>~/.texra/memories/</code></td></tr><tr><td><strong>Project memory</strong></td><td>What is true of this project</td><td><code>~/.texra/v1/workspace-storage/&lt;workspace-name&gt;-&lt;hash&gt;/memories/</code></td></tr></tbody></table><p>Neither folder is inside your repository, so a project you clone brings no memory with it, and nothing remembered is committed. The VS Code extension, the desktop app, and the CLI share both folders.</p><p>Each folder has an index, <code>MEMORY.md</code>, with one line per note. The index is the only part of memory shown automatically: its current text is in the assistant&#39;s instructions at every request, so a note written in one conversation is listed in the next, and a note written mid-task is listed at the next step. The notes themselves are read when a line of the index looks relevant. Only the first 16,000 characters of an index are shown, so keep it to one short line per note.</p><p>Instructions you want followed in full, every time, belong in <a href="./customizing.html#project-instructions-agentsmd"><code>AGENTS.md</code></a>, which is loaded whole; memory is for what the assistant learns as it works.</p><h2 id="enabling-memory" tabindex="-1">Enabling memory <a class="header-anchor" href="#enabling-memory" aria-label="Permalink to “Enabling memory”">​</a></h2><p>Memory is <strong>on by default</strong>. To turn it off, open <strong>Settings</strong> (Command Palette → <code>TeXRA: Open Settings</code>), switch to the <strong>Memory</strong> tab, and flip the <strong>Enable memory for chat agents</strong> switch. While it is off, agents are given neither folder and no index.</p><p>Memory needs the file tools: an agent with no tool to read a file has no memory. Writing a note is a file edit like any other, so under <strong>Ask</strong> you review it; under the default, Auto-approve, it is written without asking.</p><h2 id="reading-and-editing-notes-yourself" tabindex="-1">Reading and editing notes yourself <a class="header-anchor" href="#reading-and-editing-notes-yourself" aria-label="Permalink to “Reading and editing notes yourself”">​</a></h2><p>The <strong>Memory</strong> tab has two buttons, <strong>Open your memory folder</strong> and <strong>Open this project&#39;s memory folder</strong>. The notes are plain files: read them, edit them, delete them, or add your own in any editor. To make sure the assistant sees a note you wrote, add a line for it to that folder&#39;s <code>MEMORY.md</code>.</p><p>In a task&#39;s view, a note the assistant writes appears as a file edit, with its diff.</p><h2 id="memory-is-shared-across-a-task" tabindex="-1">Memory is shared across a task <a class="header-anchor" href="#memory-is-shared-across-a-task" aria-label="Permalink to “Memory is shared across a task”">​</a></h2><p>Within a single run, the assistant and every helper agent it starts read and write the <strong>same</strong> two folders. A helper agent can write a note that the assistant sees at its next step, and that note survives into the next conversation.</p><p>The assistant can also keep programs for itself in the project folder: a file at <code>programs/&lt;name&gt;.js</code> there is the program <code>own:&lt;name&gt;</code> (see <a href="./texra-cli.html">the CLI guide</a>).</p><h2 id="when-not-to-use-memory" tabindex="-1">When <em>not</em> to use memory <a class="header-anchor" href="#when-not-to-use-memory" aria-label="Permalink to “When not to use memory”">​</a></h2><ul><li><strong>Throwaway intermediate work</strong>: that belongs in the agent&#39;s plan or scratch reasoning, not in a saved note.</li><li><strong>Sensitive credentials</strong>: memory files are plain Markdown on disk; treat them like any other file.</li><li><strong>Auto-generated logs</strong>: runs already have run storage for artifacts; don&#39;t duplicate them as memories.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to “Related”">​</a></h2><ul><li><a href="./progress-board.html">Tasks view</a>: see what an agent is doing in real time, including the notes it reads and writes</li><li><a href="./configuration.html">Configuration</a>: the full list of Settings tabs</li><li><a href="./customizing.html">Tailoring TeXRA</a>: project instructions, skills, plugins, and your own programs</li></ul>`,25)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};